        getPerformanceSummary(history) {
            if (!history.length) return {};
            var T = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k){return k;};

            var revenues = history.map(function(r) { return r.results ? r.results.revenue || 0 : 0; });
            var profits = history.map(function(r) { return r.results ? r.results.grossProfit || 0 : 0; });
            var totalRevenue = revenues.reduce(function(s, v) { return s + v; }, 0);
            var totalProfit = profits.reduce(function(s, v) { return s + v; }, 0);
            var avgMargin = totalRevenue > 0 ? Math.round(totalProfit / totalRevenue * 100) : 0;

            var lastRound = history[history.length - 1];
            var finalUtil = lastRound.results ? lastRound.results.utilization || 0 : 0;
            var finalSat = lastRound.results ? lastRound.results.satisfaction || 0 : 0;

            var revenueScore = Math.min(25, Math.round((totalRevenue / 42000000 - 1) * 100));
            var marginScore = Math.min(25, Math.round(avgMargin * 0.4));
            var utilScore = Math.min(20, Math.round((finalUtil - 55) * 0.57));
            var satScore = Math.min(20, Math.round((finalSat - 50) * 0.4));
            var retScore = 10;
            var totalScore = Math.max(0, revenueScore + marginScore + utilScore + satScore + retScore);

            var performance = T('perf_needs');
            if (totalScore >= 70) performance = T('perf_excellent');
            else if (totalScore >= 55) performance = T('perf_good');
            else if (totalScore >= 40) performance = T('perf_satisfactory');

            var insights = [];
            if (avgMargin >= 60) insights.push(T('ins_margin_strong'));
            if (avgMargin < 55) insights.push(T('ins_margin_weak'));
            if (finalUtil >= 73 && finalUtil <= 80) insights.push(T('ins_util_sweet'));
            if (finalUtil > 85) insights.push(T('ins_util_high'));
            if (finalUtil < 68) insights.push(T('ins_util_low'));
            if (finalSat >= 80) insights.push(T('ins_sat_high'));
            if (finalSat < 70) insights.push(T('ins_sat_low'));

            return {
                totalRevenue: totalRevenue,
                totalProfit: totalProfit,
                avgMargin: avgMargin,
                finalUtilization: finalUtil,
                finalSatisfaction: finalSat,
                totalScore: totalScore,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.grossProfit < 0) return window.mySimulation.t('hint_loss');
            if (results.turnover > 3) return window.mySimulation.t('hint_turnover');
            if (results.utilization > 85) return window.mySimulation.t('hint_burnout');
            if (results.utilization < 65) return window.mySimulation.t('hint_low_util');
            if (results.satisfaction < 70) return window.mySimulation.t('hint_low_sat');
            if (results.clientsLost > 1) return window.mySimulation.t('hint_churn');
            if (results.margin > 62) return window.mySimulation.t('hint_strong_margin');
            return null;
        }

