        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUND_COUNT - 1);
            var key = 'round' + (idx + 1);
            var T = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k){return k;};

            var titleEl = document.getElementById('briefingTitle');
            if (titleEl) titleEl.textContent = T(key + '_title');

            var descEl = document.getElementById('briefingText');
            if (descEl) descEl.textContent = T(key + '_desc');

            var eventEl = document.getElementById('eventText');
            if (eventEl) eventEl.innerHTML = T(key + '_event');
        }
